import { mkdirSync, mkdtempSync, realpathSync, rmSync, symlinkSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, describe, expect, it } from 'vitest';
import { sharedSoundFile, type SharedSoundLookups } from './shared-sound';

/*
 * A sound a phone plays (Session 54, D3): its own file, inside the media folder by its real path, only while a
 * playlist shared with phones has it; never another sound, a picture or a video by this way, nor a missing file.
 * Generated bytes and made-up ids only.
 */

let root = '';
afterEach(() => {
  if (root) rmSync(root, { recursive: true, force: true });
  root = '';
});

function folders() {
  root = mkdtempSync(join(tmpdir(), 'drashti-shared-sound-'));
  const mediaDir = join(root, 'Media');
  const outside = join(root, 'Elsewhere');
  mkdirSync(join(mediaDir, 'ab'), { recursive: true });
  mkdirSync(outside);
  writeFileSync(join(mediaDir, 'ab', 'tone.wav'), Buffer.alloc(16, 1));
  writeFileSync(join(outside, 'private.wav'), Buffer.alloc(16, 2));
  // A folder in the media folder that is a link to one outside it.
  symlinkSync(outside, join(mediaDir, 'linked'), 'junction');
  return mediaDir;
}

/** The library as the lookups read it: a shared sound, one not shared, a picture shared, and a missing sound. */
function lookups(
  mediaDir: string,
  shared = new Set(['tone', 'picture', 'gone', 'away']),
): SharedSoundLookups {
  const rows: Record<string, { kind: 'image' | 'video' | 'audio'; path: string; missing: boolean }> = {
    tone: { kind: 'audio', path: 'ab/tone.wav', missing: false },
    chime: { kind: 'audio', path: 'ab/tone.wav', missing: false },
    picture: { kind: 'image', path: 'ab/tone.wav', missing: false },
    gone: { kind: 'audio', path: 'ab/gone.wav', missing: true },
    away: { kind: 'audio', path: 'linked/private.wav', missing: false },
  };
  return { mediaDir, kindAndFile: (id) => rows[id] ?? null, shared: (id) => shared.has(id) };
}

describe('a sound a phone plays from a shared playlist (Session 54, D3)', () => {
  it('is its file inside the media folder, by its real path, while a shared playlist has it', () => {
    const mediaDir = folders();
    expect(sharedSoundFile('tone', lookups(mediaDir))).toBe(
      realpathSync.native(join(mediaDir, 'ab', 'tone.wav')),
    );
    // No longer shared: none.
    expect(sharedSoundFile('tone', lookups(mediaDir, new Set()))).toBeNull();
  });

  it('is never a sound no shared playlist has, a picture or a video, a missing file, or a made-up id', () => {
    const mediaDir = folders();
    const library = lookups(mediaDir);
    for (const id of ['chime', 'picture', 'gone', 'nothing', '../tone', 'tone_s50', ''])
      expect(sharedSoundFile(id, library), id).toBeNull();
  });

  it('is refused through a link in the media folder that leads out of it (SEC-10)', () => {
    const mediaDir = folders();
    expect(sharedSoundFile('away', lookups(mediaDir))).toBeNull();
  });
});
